Json build_industrial(const Json&recipe){Json local=recipe;std::string preset=local.value("preset","industrial_solid");local.erase("preset");if(preset!="industrial_window"&&preset!="industrial_solid"&&preset!="industrial_vented"&&preset!="industrial_louvered")throw std::runtime_error("Unknown industrial preset");Json operations=local.value("operations",Json::array());local.erase("operations");std::string glazing=local.value("glazing","intact"),finish=local.value("finish","weathered_gray");local.erase("glazing");local.erase("finish");if(finish!="weathered_gray"&&finish!="charcoal")throw std::runtime_error("Unknown finish");if(!operations.is_array())throw std::runtime_error("operations must be a list");if(glazing!="intact"&&glazing!="broken"&&glazing!="empty")throw std::runtime_error("Unknown glazing state");bool win=preset=="industrial_window";Json defaults={{"kind",win?"window":"door"},{"width",win?1.16:1.0},{"height",win?1.25:2.1},{"thickness",.052},{"seed",29}};defaults.update(local);auto r=normalize_recipe(defaults);r["finish"]=finish;if(r["kind"]!=(win?"window":"door"))throw std::runtime_error("kind and preset mismatch");if(win&&r["angle"].get<double>()!=0)throw std::runtime_error("Fixed glazing has no opening angle");Builder b(r);frame(b,win);if(win)window(b,glazing);else door(b,preset);b.scene["recipe"]=r;b.scene["recipe"].update({{"preset",preset},{"glazing",glazing},{"operations",operations}});auto&m=b.scene["metadata"];m.update({{"generator","JericoProceduralCppLab/industrial.cpp"},{"preset",preset},{"authoring_only",true},{"physics_policy","Geometry, local axes and support references only. Engine chooses joint type, lock, strength, looseness, constraints and damage response."},{"source_geometry","Original procedural geometry and original damage algorithms; no imported add-on code or assets"},{"damage_operations",Json::array()},{"support_validation","Material sample queries on generated source/cut solids; not a strength simulation."}});m["clearance"]={{"method","not_applicable_fixed_frame"},{"applicable",false},{"samples",0},{"leaf_pair_samples",0},{"collisions",Json::array()},{"scope","Fixed frame has no moving leaf; no motion sweep was evaluated."}};m["clearance"]=clearance_sweep(b.scene);if(!operations.empty())return apply_operations(b.scene,operations);return b.scene;}
